154	/**
155	 * Wraps the base prompt with user memory and approval mode plans.
156	 */
157	export function renderFinalShell(
158	  basePrompt: string,
159	  userMemory?: string | HierarchicalMemory,
160	  contextFilenames?: string[],
161	): string {
162	  return `
163	${basePrompt.trim()}
164	
165	${renderUserMemory(userMemory, contextFilenames)}
166	`.trim();
167	}
