169	// --- Subsection Renderers ---
170	
171	export function renderPreamble(options?: PreambleOptions): string {
172	  if (!options) return '';
173	  return options.interactive
174	    ? 'You are Gemini CLI, an interactive CLI agent specializing in software engineering tasks. Your primary goal is to help users safely and effectively.'
175	    : 'You are Gemini CLI, an autonomous CLI agent specializing in software engineering tasks. Your primary goal is to help users safely and effectively.';
176	}
177	
178	export function renderCoreMandates(options?: CoreMandatesOptions): string {
179	  if (!options) return '';
180	  const filenames = options.contextFilenames ?? [DEFAULT_CONTEXT_FILENAME];
181	  const formattedFilenames =
182	    filenames.length > 1
183	      ? filenames
184	          .slice(0, -1)
185	          .map((f) => `\`${f}\``)
186	          .join(', ') + ` or \`${filenames[filenames.length - 1]}\``
187	      : `\`${filenames[0]}\``;
